import { db } from './db';

export async function agregar(clienteId: number, productoId: number, cantidad: number) {
  await db.query(
    `INSERT INTO carrito_items (cliente_id, producto_id, cantidad) VALUES ($1, $2, $3)
     ON CONFLICT (cliente_id, producto_id) DO UPDATE SET cantidad = carrito_items.cantidad + EXCLUDED.cantidad`,
    [clienteId, productoId, cantidad],
  );
}

files.db/schema.sql:
CREATE TABLE productos (
  id SERIAL PRIMARY KEY,
  nombre TEXT NOT NULL,
  precio NUMERIC(12,2) NOT NULL,
  activo BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE pedidos (
  id SERIAL PRIMARY KEY,
  cliente_id INT NOT NULL,
  estado TEXT NOT NULL CHECK (estado IN ('pendiente', 'enviado', 'entregado', 'cancelado'))
);

CREATE TABLE pedido_items (
  pedido_id INT NOT NULL REFERENCES pedidos(id),
  producto_id INT NOT NULL REFERENCES productos(id),
  cantidad INT NOT NULL
);

CREATE TABLE carrito_items (
  cliente_id INT NOT NULL,
  producto_id INT NOT NULL REFERENCES productos(id),
  cantidad INT NOT NULL,
  UNIQUE (cliente_id, producto_id)
);
